const widgetCSS=`body{font:14px/1.6 system-ui,sans-serif;margin:0;padding:16px;color:#eef0f3;background:#111215}h2{font-size:18px;margin:0 0 12px}p{margin:8px 0}ul{list-style:none;padding:0;margin:0}li{padding:12px 0;border-bottom:1px solid #35373d;overflow-wrap:anywhere}button{font:inherit;min-height:48px;padding:8px 14px;color:inherit;background:#25272c;border:1px solid #53555b;border-radius:6px;cursor:pointer}button:disabled{opacity:.6;cursor:wait}.row{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}.muted{color:#b4b6bd}[role=status]{overflow-wrap:anywhere}button:focus-visible{outline:2px solid #fff;outline-offset:3px}`;

export const WORKSHOP_EXAMPLES=[
  {id:'aispace',label:'AISpace 参考布局',package:{apiVersion:1,kind:'theme',name:'AISpace 参考布局',description:'蓝绿顶栏、浅色侧栏、紧凑任务表格和独立日志标签；保留现有平台全部操作。',theme:{tokens:{'--bg':'#f4f6fa','--bg-1':'#ffffff','--bg-2':'#eef3f8','--bg-3':'#e5ecf4','--bg-4':'#dce5ef','--line':'#e2e8f0','--line-2':'#cbd5e1','--line-3':'#94a3b8','--ink':'#243247','--ink-2':'#46566c','--ink-3':'#617188','--ink-4':'#64748b','--primary':'#246fdf','--primary-hover':'#195abb','--on-primary':'#ffffff','--on-danger':'#ffffff','--run':'#148650','--queue':'#995e09','--prep':'#246fdf','--err':'#c53440','--seg-on':'#ffffff','--code-bg':'#eaf0f6','--ring':'#246fdf'},density:'compact',width:'wide',columns:2,layout:'aispace'}}},
  {id:'light',label:'浅色紧凑主题',package:{apiVersion:1,kind:'theme',name:'浅色紧凑',description:'浅色界面、紧凑间距、宽工作台和双列小组件。',theme:{tokens:{'--bg':'#f3f3f0','--bg-1':'#ffffff','--bg-2':'#ecece8','--bg-3':'#e3e3de','--bg-4':'#d8d8d2','--line':'#deded8','--line-2':'#cdcdc6','--line-3':'#b9b9b2','--ink':'#0b0c0e','--ink-2':'#45474d','--ink-3':'#63656c','--ink-4':'#73736d','--primary':'#0b0c0e','--primary-hover':'#2a2b30','--on-primary':'#ffffff','--on-danger':'#ffffff','--run':'#0a7a46','--queue':'#985800','--prep':'#0a62b8','--err':'#c01d2c','--seg-on':'#ffffff','--code-bg':'#0b0c0e12','--ring':'#0b0c0e'},density:'compact',width:'wide',columns:2}}},
  {id:'gpu',label:'GPU 概览插件',package:{apiVersion:1,kind:'plugin',name:'GPU 概览',description:'查看已授权服务器的 GPU 指标；点击刷新读取当前快照。',permissions:['resources.read','ui.navigate'],html:'<div class="row"><h2>GPU 概览</h2><button id="refresh">刷新</button></div><p id="status" role="status"></p><ul id="machines"></ul><button id="open">打开算力总览</button>',css:widgetCSS,script:`const status=document.querySelector('#status'),list=document.querySelector('#machines'),button=document.querySelector('#refresh');
async function refresh(){button.disabled=true;status.textContent='正在读取…';try{const data=await stargate.call('resources.read',{});list.replaceChildren();status.textContent=data.stale?'监控待更新':data.checkedAt?'更新于 '+data.checkedAt:'更新时间未确认';for(const machine of data.machines){const row=document.createElement('li'),title=document.createElement('strong');title.textContent=machine.id;row.append(title);const text=document.createElement('p');text.textContent=machine.reachable===false?'服务器不可达':machine.gpus.length?machine.gpus.map(gpu=>'GPU '+gpu.index+' · '+(gpu.utilization===null?'利用率未知':gpu.utilization+'%')+' · '+(gpu.memoryUsedMiB===null||gpu.memoryTotalMiB===null?'显存未知':gpu.memoryUsedMiB+'/'+gpu.memoryTotalMiB+' MiB')).join(' / '):'GPU 数据待确认';row.append(text);list.append(row);}if(!data.machines.length)status.textContent='暂无已授权服务器';}catch(error){status.textContent=error.message;}finally{button.disabled=false;}}
button.addEventListener('click',refresh);window.addEventListener('stargate:update',()=>{if(!button.disabled)refresh();});document.querySelector('#open').addEventListener('click',()=>stargate.call('ui.navigate',{page:'resources'}).catch(error=>status.textContent=error.message));refresh();`}},
  {id:'jobs',label:'我的任务插件',package:{apiVersion:1,kind:'plugin',name:'我的任务',description:'查看本人任务；取消操作仍须在平台确认，不会自动停止训练。',permissions:['jobs.read','jobs.cancel','ui.navigate'],html:'<div class="row"><h2>我的任务</h2><button id="refresh">刷新</button></div><p id="status" role="status"></p><ul id="jobs"></ul><button id="open">打开工作台</button>',css:widgetCSS,script:`const status=document.querySelector('#status'),list=document.querySelector('#jobs'),refreshButton=document.querySelector('#refresh');
async function refresh(){refreshButton.disabled=true;status.textContent='正在读取…';try{const data=await stargate.call('jobs.read',{});list.replaceChildren();status.textContent=data.jobs.length?'仅显示本人任务':'暂无本人任务';for(const job of data.jobs){const row=document.createElement('li'),title=document.createElement('strong'),meta=document.createElement('p');title.textContent=job.name||job.id;meta.textContent=job.state+' · '+job.machine+' · '+job.cards+' 张';row.append(title,meta);if(!['SUCCEEDED','FAILED','CANCELED'].includes(job.state)){const cancel=document.createElement('button');cancel.textContent='取消任务';cancel.addEventListener('click',async()=>{cancel.disabled=true;try{const receipt=await stargate.call('jobs.cancel',{jobId:job.id});status.textContent=receipt.cancelRequested?'已请求取消，等待停止确认':'任务状态：'+receipt.state;await refresh();}catch(error){status.textContent=error.message;}finally{cancel.disabled=false;}});row.append(cancel);}list.append(row);}}catch(error){status.textContent=error.message;}finally{refreshButton.disabled=false;}}
refreshButton.addEventListener('click',refresh);window.addEventListener('stargate:update',()=>{if(!refreshButton.disabled)refresh();});document.querySelector('#open').addEventListener('click',()=>stargate.call('ui.navigate',{page:'work'}).catch(error=>status.textContent=error.message));refresh();`}},
];
